extern "C" int entry(int r1, int r2, int atags){
    os::kernel::init(r1, r2, atags);

    void* heap_start   = os::memory::get_kernel_end();
    uint32_t heap_size = os::memory::get_memory_size();

    os::memory::best_fit_heap heap(heap_start, heap_size);

    char* str = (char*)heap.malloc(100);

    os::console::puts("Kernel Started\n");
    for(uint32_t i = 0; ; ++i){
        os::console::puts("Enter Text: ");
        os::console::getline(str, 99);
        os::console::putc('[');
        os::console::putu32(i);
        os::console::puts("] You typed: ");
        os::console::puts(str);
        os::console::putc('\n');
    }

    heap.free(str);

    os::kernel::destroy();
}

extern crate rand;
extern crate warble;

use rand::rngs::OsRng;
use std::str;
use strobe_rs::{SecParam, Strobe};
use warble::{AeadReceiver, AeadSender, Warblee, Warbler, MAC_LEN};

fn main() {
    // create and key Strobe transcripts.
    let mut ta = Strobe::new(b"warbletest", SecParam::B128);
    let mut tb = Strobe::new(b"warbletest", SecParam::B128);
    ta.key(b"secretkey", false);
    tb.key(b"secretkey", false);

    // ta is the sender's transcript, tb is the receiver's transcript
    let session_id = &mut [0u8; 8];
    let mut sender = Warbler::new(ta, &mut OsRng, Some(session_id));
    let mut receiver = Warblee::new(tb, Some(session_id));

    let mut txts: [&[u8]; 2] = [b"hello world", b"second message"];
    for txt in txts.iter_mut() {
        println!("Sending message: {:?}", str::from_utf8(txt).unwrap());
        let ad = Some("additional stuff".as_bytes());
        let mut mac = [0u8; MAC_LEN];
        let nonce = &mut 0u32.to_be_bytes();

        let mut plaintext = [0u8; 20];
        for (m, t) in plaintext.iter_mut().zip(txt.iter()) {
            *m = *t
        }
        assert!(sender
            .send(Some(&mut plaintext), ad, &mut mac, nonce)
            .is_ok());
        let mut ciphertext = plaintext; // renaming for readability
        assert!(receiver
            .receive(Some(&mut ciphertext), ad, &mut mac, Some(nonce))
            .is_ok());
        let round_trip = ciphertext;
        println!(
            "Received message: {:?}",
            str::from_utf8(&round_trip).unwrap()
        );
    }
}

Select records from database with JdbcTemplate

With this example we are going to demonstrate how to select records from a database using the JdbcTemplate class provided by the Spring Framework. The JdbcTemplate class is the central class in the JDBC core package. It simplifies the use of JDBC and helps to avoid common errors. It executes core JDBC workflow, leaving application code to provide SQL and extract results. This class executes SQL queries or updates, initiating iteration over ResultSets and catching JDBC exceptions. In short, to select records from a database using the JdbcTemplate class you should:

  • Use the DataSource class, a utility class that provides connection to the database. It is part of the JDBC specification and allows a container or a framework to hide connection pooling and transaction management issues from the application code. We implement it using the org.springframework.jdbc.datasource.DriverManagerDataSource. Set the credentials needed to the datasource, using the inherited methods setPassword(String password), setUrl(String url) and setUsername(String username) API methods of AbstractDriverBasedDataSource class, as also the setDriverClassName(String driverClassName) API method of DriverManagerDataSource. Create a new Datasource object having the above configuration. Here in getDatasource() method we create a new Datasource and configure it.
  • Create a new JdbcTemplate object, with the given datasource to obtain connections from.
  • Use the queryForList(String sql) API method of JdbcTemplate class to execute a query for a result list, with the given static SQL select query. The results will be mapped to a List (one entry for each row) of result objects, each of them matching the specified element type. 
  • Iterate over the List of the results to get the values of each column per row.

Let’s take a look at the code snippet that follows:

package com.javacodegeeks.snippets.enterprise;

import java.util.Iterator;
import java.util.List;
import java.util.Map;

import javax.sql.DataSource;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;

public class SelectRecordsFromDatabaseWithJdbcTemplate {
	private static final String driverClassName = "com.mysql.jdbc.Driver";
	private static final String url = "jdbc:mysql://localhost/companydb";
	private static final String dbUsername = "jcg";
	private static final String dbPassword = "jcg";

	private static final String selectSql = "SELECT * FROM employee";

	private static DataSource dataSource;
	public static void main(String[] args) throws Exception {
		dataSource = getDataSource();
		JdbcTemplate template = new JdbcTemplate(dataSource);
		List<Map<String, Object>> employees = template.queryForList(selectSql);
		if (employees!=null && !employees.isEmpty()) {
			for (Map<String, Object> employee : employees) {
				for (Iterator<Map.Entry<String, Object>> it = employee.entrySet().iterator(); it.hasNext();) {
					Map.Entry<String, Object> entry = it.next();
					String key = entry.getKey();
					Object value = entry.getValue();
					System.out.println(key + " = " + value);
	public static DriverManagerDataSource getDataSource() {

  DriverManagerDataSource dataSource = new DriverManagerDataSource();

  dataSource.setDriverClassName(driverClassName);

  dataSource.setUrl(url);

  dataSource.setUsername(dbUsername);

  dataSource.setPassword(dbPassword);

  return dataSource;

